import fs from 'node:fs/promises';
import path from 'node:path';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {createHash} from 'node:crypto';
import {TARGET_SKILL_COLLECTIONS} from '../../../scripts/skill-collection-registry.mjs';
import {derivePackageAcceptanceObligations} from '../../../scripts/managed-skill-input.mjs';
import {captureMigrationPath} from '../../../scripts/migration-filesystem.mjs';
import {adoptionSourceContentSha256} from '../../../scripts/adoption-acceptance.mjs';
const root=process.cwd(), dir='.unlazy/release-447/source-review', revision='dcbc75b4a69ef2d7dfc39e582afd005dc2264b0c', baseline='fab40148cffd0c1ef3e0de6b4d44bc91bd411ca3';
const sha=b=>createHash('sha256').update(b).digest('hex');
const json=async p=>JSON.parse(await fs.readFile(p));
const exec=promisify(execFile);
const git=async(...args)=>(await exec('git',args,{cwd:root,maxBuffer:20*1024*1024,encoding:'buffer'})).stdout;
const notes=await json(`${dir}/assessment-notes.json`), provenance=await json('config/skill-provenance.json'), audit=await json('docs/validation/upstream-adoption-acceptance.json'), lex=await json('tests/fixtures/lean-execution-adoption/lex12-acceptance.json'), migrations=await json('config/skill-migrations.json');
const packages=TARGET_SKILL_COLLECTIONS.map(c=>({id:c.id,obligations:derivePackageAcceptanceObligations(c.id,migrations),hosts:['codex','claude-code','pi'].map(host=>({host,status:'pending-current-package-acceptance',checks:derivePackageAcceptanceObligations(c.id,migrations).requiredChecks.map(check=>({check,decision:check==='native-discovery'?'Current exact-host source activation needs independent qualification; metadata, SDK, transient loading and installed-host acceptance are distinct.':check==='behavior'?'Reuse only named reviewed stimuli; additive source correctness may be accepted without universal model reliability. Raw dollar-literal host expansion caveat remains.':check==='video-runtime'?'Retain unchanged measured Linux 0.8.77 artifacts/profile only; fresh pinned render unavailable and required unsupported selected providers still block.':check==='unlazy-runtime'?'Retain unchanged Linux engine evidence plus fresh bounded local checks; no Windows/detached containment or hook installation claim.':'Current structural validation and exact closure/notices bindings required; historical evidence reusable when unchanged.'}))}))}));
const sourcePaths=[...new Set([...packages.flatMap(p=>p.obligations.sourcePaths),...Object.keys(audit.sources)])].sort();
const sources={}; for(const p of sourcePaths){const s=await captureMigrationPath(path.join(root,p));sources[p]={kind:s.kind,contentSha256:adoptionSourceContentSha256(s),historicalContentSha256:audit.sources[p]?.contentSha256??null,historicalBindingMatches:audit.sources[p]?.contentSha256===adoptionSourceContentSha256(s)};}
const evidence={};
const evidencePaths=[...new Set([...Object.values(audit.evidence).map(r=>r.path),'AGENTS.md','docs/specs/quickstark-upstream-adoption.md','docs/skill-run-contract.md','scripts/managed-skill-input.mjs','scripts/adoption-acceptance.mjs','tests/lean-execution.test.mjs','docs/validation/upstream-adoption-acceptance.json','config/skill-provenance.json',...['lex12-acceptance.json','lex12-noninstall-evidence.json','lex12-mobile-report-resolution.json','historical-acceptance.json','source-review-final.json','evaluation-disposition.json'].map(p=>'tests/fixtures/lean-execution-adoption/'+p)])].sort();
for(const p of evidencePaths) evidence[p]=sha(await fs.readFile(p));
const historicalEvidence=Object.entries(audit.evidence).map(([id,r])=>({id,path:r.path,expectedSHA256:r.sha256,currentSHA256:evidence[r.path],matches:r.sha256===evidence[r.path]}));
const capabilities=[];
for(const c of provenance.target.capabilities){const body=await fs.readFile(c.path);let prior=null;try{prior=await git('show',`${baseline}:${c.path}`)}catch{};capabilities.push({id:c.id,name:c.name,package:c.package,role:c.role,path:c.path,sourceSHA256:sha(body),baselineIds:c.baselineIds,currentDecision:c.decision,currentDecisionSHA256:sha(JSON.stringify(c.decision)),baselineSHA256:prior?sha(prior):null,unchangedFromPublishedBaseline:prior?sha(prior)===sha(body):false,assessment:notes.sourceDecisions[c.name]??'Preserve unchanged historical source decision and its qualifications. This pass does not expand its behavioral/runtime/platform scope.',scopedDecision:notes.sourceDecisions[c.name]?'correctness-source-review-accepted-candidate':'preserve-existing-decision',adoptionApplied:false});}
const changedCanonicalPaths=(await git('diff','--name-only',baseline,revision,'--','skills','docs/skill-run-contract.md')).toString().trim().split('\n').filter(Boolean);
const delta=[];for(const p of changedCanonicalPaths){const current=await fs.readFile(p),prior=await git('show',`${baseline}:${p}`);delta.push({path:p,sourceSHA256:sha(current),baselineSHA256:sha(prior),assessment:p.endsWith('dependency-index.json')?'Derived index updated for changed private content; original source identities/hashes preserved. Frontend records retain pre-LEX derived history.':p==='docs/skill-run-contract.md'?'Additive shared delegation policy preserves root ownership, bounded scope, host controls, explicit budgets and required parent verification.':capabilities.find(c=>c.path===p)?.assessment??(p.includes('token-economy')?notes.sourceDecisions['qs-unlazy']:'Private guidance independently reviewed through its matching owner assessment.'),scopedDecision:'accept-source-correctness-only-candidate'});}
const closures=[];
for(const c of provenance.target.closures){const index=await json(c.path),base=path.dirname(path.dirname(c.path)),entries=[];if(c.owner==='qs-video'){for(const f of index.files.filter(f=>f.destinationPath))entries.push({path:path.join(base,f.destinationPath),expectedSHA256:f.derivedSha256});for(const f of index.localFiles)entries.push({path:path.join(base,f.path),expectedSHA256:f.sha256});}else for(const f of index.files)entries.push({path:path.join(base,index.moduleRoot,f.destination),expectedSHA256:f.derivedSha256});for(const e of entries){e.actualSHA256=sha(await fs.readFile(e.path));e.matches=e.actualSHA256===e.expectedSHA256; e.unchangedFromPublishedBaseline=sha(await git('show',`${baseline}:${e.path}`))===e.actualSHA256;}
closures.push({owner:c.owner,path:c.path,indexSHA256:sha(await fs.readFile(c.path)),currentAdoptionStatus:c.adoptionStatus,adoptedRevision:c.adoptedRevision,moduleCount:index.modules?.length??1,records:index.files.length,entries,scopedDecision:c.owner==='qs-video'?'Source-closure preservation accepted candidate: unchanged 21 modules, original records and local files. Runtime reuse limited to the historical measured local workflow at its exact pin/profile.':'Source-closure preservation with independently reviewed token-economy adaptation accepted candidate: complete 23-file index retains original/derived hashes; actual engine scripts unchanged. Runtime scope remains Linux/Node only.',adoptionApplied:false});}
const criteria=Object.entries(notes.criteria).map(([id,[decision,rationale,requiredBeforeCurrentAcceptance]])=>({id,decision,rationale,requiredBeforeCurrentAcceptance,historicalStatus:audit.criteria[id].status,historicalEvidence:audit.criteria[id].evidence}));
const report={schemaVersion:1,kind:'independent-source-and-criterion-assessment-not-acceptance-receipt',revision,version:'4.4.7',publishedBaseline:baseline,metadataBindingPolicy:{immutableAnchors:['docs/validation/upstream-adoption-acceptance.json','config/skill-provenance.json','tests/lean-execution.test.mjs'],rule:'Read pre-advance anchors from the exact reviewed Git revision, independently of later current metadata. Current source bodies and closure resources remain live-bound; every old capability decision must survive verbatim in the current decision/previous chain. Root separately verifies current acceptance and regenerated outputs after advancement.'},scope:'Source/criterion acceptance assessment only. No adopted status, current receipt, install, publication, source or provenance mutation. Decisions are review candidates for root integration, not manufactured whole-package acceptance.',notPresent:['docs/specs/quickstark-lean-execution.md'],sourceSnapshots:sources,evidenceSHA256:evidence,historicalEvidence,changedCanonical:delta,capabilities,criteria,packages,closures,gapMatrix:packages.flatMap(p=>p.hosts.map(h=>({packageId:p.id,host:h.host,status:'pending',sourceReview:'independent scoped correctness/source-preservation candidates supplied; root must append actual decisions',criteria:p.obligations.requiredCriteria.map(id=>({id,decision:criteria.find(c=>c.id===id).decision,nextEvidence:criteria.find(c=>c.id===id).requiredBeforeCurrentAcceptance})),requiredChecks:h.checks}))),historyMigration:{preserve:['lex12-acceptance.json and original sourceReviews/untouchedDecisions/closureAcceptance','lex12-noninstall-evidence.json including B8','lex12-mobile-report-resolution.json including MR failures and MT scope','historical audit sources/packages/criteria and exact original decision chains'],seam:'Before advancing, archive exact dcbc75b current audit and provenance as new append-only fixtures. Keep original lex12 record byte-identical. Test lex12 historical claims against archived audit/provenance; separately assert current decision history contains each exact old decision and current derivation/closure/adoption decisions bind current source. Historical receipt rejection test must use archived audit and exact unchanged mismatch set. Add a distinct current acceptance test; do not weaken pending/unknown assertions into broad alternatives.',newAudit:'Create new explicit current decisions and host-check evidence, with cited scoped rationale, before capturing replacement source snapshots. Update current source bindings only after decisions/provenance changes and generated sync; audit file is not in sourcePaths, avoiding a direct self-hash cycle. Commit tracked inputs and rerun release validator against immutable candidate. Preserve retained-baseline AC08/09 and exact no-new-install/no-efficiency qualifications.'},passes:[{pass:1,result:'Complete source, criterion, capability and 18 package/host gap assessment implemented.'},{pass:2,result:'Expert reread compared additive canonical delta with published 4.4.6 and historical obligations; caught 2 older pending owners in addition to 19 reviewed LEX owners.'},{pass:3,result:'Evidence defect hunt verified 145 historical evidence hashes, 34 stale source bindings, closure resource hashes, original/derived distinctions and legacy context-expansion caveat.'},{pass:4,result:'Polish preserves explicit candidate-only decisions, current host gaps, retained baseline and immutable historical migration seam. No remaining source-content defect found in bounded delta.'}],findings:[],remaining:'Root must integrate scoped decisions, independently returned behavioral/runtime/discovery decisions and exact current validation; package receipts and installed-host acceptance are not granted by this report.'};
await fs.writeFile(`${dir}/source-review.json`,JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({capabilities:capabilities.length,criteria:criteria.length,packages:packages.length,hostRows:report.gapMatrix.length,historicalEvidence:historicalEvidence.length,badHistoricalEvidence:historicalEvidence.filter(r=>!r.matches).length,staleSources:Object.values(sources).filter(s=>!s.historicalBindingMatches).length,closures:closures.map(c=>({owner:c.owner,entries:c.entries.length,bad:c.entries.filter(e=>!e.matches).length,changed:c.entries.filter(e=>!e.unchangedFromPublishedBaseline).map(e=>e.path)}))}));
